export const DAILY_MODIFIERS: DailyModifier[] = [
  { id: 'fast_ball', name: 'Fast Ball', description: 'Ball speed +50%', icon: '⚡' },
  { id: 'tiny_paddle', name: 'Tiny Paddle', description: 'Your paddle is smaller', icon: '🔍' },
