// === SPIN VISUALIZATION ===
function updateSpinVisualization(dt: number) {
  const spinMag = ball.spin.length();
  if (!ball.active || spinMag < 0.5) {
    spinLines.visible = false;
    return;
  }

  spinLines.visible = true;
  spinLines.position.copy(ball.position);

  // Rotate rings based on spin direction
  spinLines.rotation.x += ball.spin.x * dt * 2;
  spinLines.rotation.y += ball.spin.y * dt * 2;
  spinLines.rotation.z += ball.spin.z * dt * 2;

  // Opacity based on spin intensity
  const opacity = Math.min(spinMag * 0.08, 0.4);
  spinLines.children.forEach(child => {
    ((child as LineSegments).material as LineBasicMaterial).opacity = opacity;
  });
}

function updateTrail() {
  if (!trailLine) return;
  const positions = (trailLine.geometry.attributes.position as any).array as Float32Array;
  positions.fill(0);
  for (let i = 0; i < trailPoints.length - 1 && i < TRAIL_LENGTH - 1; i++) {
    const idx = i * 6;
    positions[idx] = trailPoints[i].x;
    positions[idx + 1] = trailPoints[i].y;
    positions[idx + 2] = trailPoints[i].z;
    positions[idx + 3] = trailPoints[i + 1].x;
    positions[idx + 4] = trailPoints[i + 1].y;
    positions[idx + 5] = trailPoints[i + 1].z;
  }
  trailLine.geometry.attributes.position.needsUpdate = true;

  // Speed-based trail color: blue (slow) → cyan → yellow → red (fast)
  if (ball.active) {
    const speed = ball.velocity.length();
    let trailColor: number;
    if (speed < 3) trailColor = 0x4488ff; // blue
    else if (speed < 5) trailColor = gsm.getTheme().accent; // theme accent
    else if (speed < 8) trailColor = 0xffaa00; // orange/yellow
    else trailColor = 0xff3300; // red
    (trailLine.material as LineBasicMaterial).color.set(trailColor);
    (trailLine.material as LineBasicMaterial).opacity = Math.min(0.3 + speed * 0.05, 0.7);
  }
}

function scorePoint(winner: 'player' | 'ai', reason: string) {
  ball.active = false;
  ballShadow.visible = false;
  spinLines.visible = false;

  // Edge hit achievement
  if (gsm.edgeHitsThisMatch > 0 && winner === 'player' && reason !== 'out') {
    gsm.unlockAchievement('edge_hit');
    showCommentary('edge_hit');
  }

  // Net roller achievement
  if (reason === 'winner' && winner === 'player') {
    gsm.unlockAchievement('net_roller');
  }

  // Drill mode
  if (gsm.state === 'drill_active') {
    gsm.rallyCount = 0;
    setTimeout(() => { if (gsm.state === 'drill_active') serveBall(); }, 1000);
    return;
  }

  if (gsm.mode === 'rally' || gsm.mode === 'speed') {
    if (gsm.mode === 'rally') {
      gsm.totalRallies++;
      if (gsm.rallyCount > gsm.longestRally) gsm.longestRally = gsm.rallyCount;
      showToast(`Rally: ${gsm.rallyCount} hits!`);
      if (gsm.rallyCount >= 10) showCommentary('rally_long');
    }
    gsm.rallyCount = 0;
    setTimeout(() => { if (gsm.state === 'playing') serveBall(); }, 1500);
    return;
  }

  if (gsm.mode === 'training') {
    gsm.rallyCount = 0;
    setTimeout(() => { if (gsm.state === 'playing') serveBall(); }, 1000);
    return;
  }

  gsm.pointScored(winner);

  // Round 4: Dramatic screen flash on important points
  const isImportantPoint = gsm.isMatchPoint || gsm.isDeuce || gsm.currentStreak >= 3;

  if (winner === 'player') {
    audio.playPointWon();
    gsm.unlockAchievement('first_point');

    // Round 4: Streak achievements and commentary
    if (gsm.currentStreak >= 3) {
      gsm.unlockAchievement('streak3');
      audio.playStreak(gsm.currentStreak);
      showCommentary('streak');
    }
    if (gsm.currentStreak >= 5) gsm.unlockAchievement('streak5');
    if (gsm.currentStreak >= 10) gsm.unlockAchievement('streak10');
    showToast(`${gsm.playerScore} - ${gsm.aiScore}`);
    spawnParticles(ball.position.clone(), gsm.getTheme().accent, 12);

    // Round 4: Screen flash on dramatic points
    if (isImportantPoint) {
      triggerScreenFlash(gsm.getTheme().accent, 0.4);
      audio.playDramaticPoint();
    }

    // Crowd reactions on important points
    if (gsm.isMatchPoint) {
      audio.playCrowdCheer();
      showCommentary('match_point');
    } else if (gsm.currentStreak >= 3) {
      audio.playCrowdOoh();
    }

    // Round 4: Rally comeback achievement
    if (gsm.rallyCount >= 15 && gsm.maxTrailingDeficit >= 3) {
      gsm.unlockAchievement('rally_comeback');
      showCommentary('comeback');
    }

    // Round 4: Schedule instant replay for dramatic points
    if (gsm.isMatchPoint || gsm.currentStreak >= 5 || (gsm.isDeuce && gsm.playerScore === gsm.aiScore + 1)) {
      scheduleReplay(1.5);
    }
  } else {
    audio.playPointLost();
    showToast(`${gsm.playerScore} - ${gsm.aiScore}`);
    if (gsm.isMatchPoint) {
      audio.playCrowdGasp();
      showCommentary('match_point');
      triggerScreenFlash(0xff3333, 0.3);
    }
    // Reset consecutive aces
    consecutiveAcesInRow = 0;
  }

  gsm.rallyCount = 0;

  // Check for slow-mo on match point
  if (gsm.isMatchPoint && !slowMoTriggered) {
    // Next point will get slow-mo treatment
  }

  // Trigger slow-mo for dramatic effect on match point scoring
  if (gsm.playerScore >= 10 || gsm.aiScore >= 10) {
    triggerSlowMo(1.0);
  }

  // Deuce alert
  if (gsm.isDeuce && gsm.playerScore === gsm.aiScore) {
    audio.playDeuceAlert();
    showToast('DEUCE!');
    showCommentary('deuce');
  }

  // Match point alert
  if (gsm.isMatchPoint) {
    audio.playMatchPointAlert();
  }

  // Check set win
  const setWinner = gsm.checkSetWin();
  // Daily challenge sudden death: first to 5
  const dailySuddenDeath = activeDailyMods.some(m => m.id === 'sudden_death');
  const suddenDeathWinner = dailySuddenDeath && (gsm.playerScore >= 5 || gsm.aiScore >= 5)
    ? (gsm.playerScore >= 5 ? 'player' : 'ai') as 'player' | 'ai'
    : null;
  const effectiveSetWinner = suddenDeathWinner || setWinner;
  if (effectiveSetWinner) {
    if (gsm.mode === 'quick' || gsm.mode === 'tournament' || gsm.mode === 'daily') {
      endGame();
      return;
    }
    gsm.wonSet(effectiveSetWinner);
    audio.playSetWin();
    showToast(`SET: ${gsm.playerSets} - ${gsm.aiSets}`);
    matchPointShown = false;

    const matchWinner = gsm.checkMatchWin();
    if (matchWinner) {
      endGame();
      return;
    }
  }

  // Deuce achievement
  if (gsm.playerScore >= 10 && gsm.aiScore >= 10 && winner === 'player') {
    gsm.unlockAchievement('deuce_win');
  }

  setTimeout(() => { if (gsm.state === 'playing') serveBall(); }, 1500);
}

// === AI ===
function updateAI(dt: number) {
  const diff = tournamentAI || DIFFICULTIES[gsm.difficulty];

  if (ball.active && ball.velocity.z < 0) {
    aiReactionTimer += dt;
    if (aiReactionTimer >= diff.aiReaction) {
      const timeToArrive = Math.abs((-TABLE_LENGTH / 2 + 0.15 - ball.position.z) / ball.velocity.z);
      aiTargetX = ball.position.x + ball.velocity.x * timeToArrive;
      // Read spin based on difficulty
      aiTargetX += ball.spin.y * 0.1 * (diff as any).aiSpinRead || 0;
      aiTargetX += (Math.random() - 0.5) * (1 - diff.aiAccuracy) * TABLE_WIDTH * 0.5;
      aiTargetX = Math.max(-TABLE_WIDTH / 2, Math.min(TABLE_WIDTH / 2, aiTargetX));
      aiReactionTimer = 0;
    }
  } else {
    aiTargetX = (Math.random() - 0.5) * 0.2;
    aiReactionTimer = 0;
  }

  const dx = aiTargetX - aiPaddlePos.x;
  const moveAmount = Math.sign(dx) * Math.min(Math.abs(dx), diff.aiSpeed * dt);
  aiPaddlePos.x += moveAmount;
  aiPaddlePos.x = Math.max(-TABLE_WIDTH / 2 + PADDLE_RADIUS, Math.min(TABLE_WIDTH / 2 - PADDLE_RADIUS, aiPaddlePos.x));

  aiPaddle.position.copy(aiPaddlePos);

  // AI hit ball with advanced shot selection (Round 4)
  if (ball.active && ball.lastHitBy !== 'ai') {
    const dist = ball.position.distanceTo(aiPaddlePos);
    if (dist < PADDLE_RADIUS + BALL_RADIUS + 0.04) {
      const ballHeight = ball.position.y - TABLE_HEIGHT;
      const isCounterAttack = ball.velocity.length() > 5;
      const shot = gsm.selectAIShot(gsm.difficulty, ballHeight, isCounterAttack);

      const basePower = 2 + diff.aiAggression * 4 + Math.random() * 2;
      const hitPower = basePower * shot.speedMult;
      const aimX = (Math.random() - 0.5) * shot.aimSpread * (1.5 - diff.aiAccuracy * 0.8);

      ball.velocity.set(
        aimX,
        (1.0 + hitPower * 0.25) * shot.heightMult,
        hitPower
      );
      ball.spin.set(
        -hitPower * 0.4 * diff.aiAggression * shot.spinMult,
        (Math.random() - 0.5) * 3 * diff.aiAggression * shot.spinMult,
        0
      );
      ball.lastHitBy = 'ai';
      ball.bounceCount = 0;
      gsm.rallyCount++;
      const spinAmt = ball.spin.length();

      // Shot-specific audio and VFX
      if (shot.type === 'drop') {
        audio.playDropShot();
        showCommentary('drop_shot');
        spawnParticles(ball.position.clone(), 0x88ffaa, 4);
      } else if (shot.type === 'lob') {
        audio.playLob();
        showCommentary('lob');
        spawnParticles(ball.position.clone(), 0x88aaff, 4);
      } else if (shot.type === 'smash' && hitPower > 6) {
        audio.playSmash();
        spawnParticles(ball.position.clone(), gsm.getTheme().aiPaddle, 15);
        triggerCameraShake(0.5, 0.2);
        triggerScreenFlash(gsm.getTheme().aiPaddle, 0.3);
      } else if (shot.type === 'cross_court') {
        audio.playPaddleHitPower();
        showCommentary('cross_court');
        spawnParticles(ball.position.clone(), gsm.getTheme().aiPaddle, 8);
      } else {
        audio.playPaddleHit(hitPower / 8, spinAmt);
        spawnParticles(ball.position.clone(), gsm.getTheme().aiPaddle, 6);
      }
    }
  }
}

// === VISUALS ===
function updateVisuals(dt: number) {
  playerPaddle.position.copy(playerPaddlePos);

  // Power paddle glow — brighter when paddle moves fast
  if (powerGlowMesh) {
    const paddleSpeed = playerPaddlePos.clone().sub(lastPlayerPaddlePos).length() / Math.max(dt, 0.001);
    const glowIntensity = Math.min(paddleSpeed * 0.1, 0.5);
    (powerGlowMesh.material as MeshBasicMaterial).opacity = glowIntensity;
    if (glowIntensity > 0.2) {
      // Color shifts from cyan to hot white at high speed
      const hue = Math.max(0, 1 - glowIntensity * 1.5);
      const r = 1.0;
      const g = hue;
      const b = hue;
      (powerGlowMesh.material as MeshBasicMaterial).color.setRGB(r, g, b);
    } else {
      (powerGlowMesh.material as MeshBasicMaterial).color.set(gsm.getTheme().accent);
    }
  }

  // Ghost ball effect — ball fades based on speed
  if (gsm.ghostBallActive && ball.active) {
    const speed = ball.velocity.length();
    ghostBallOpacity = Math.max(0.15, 1.0 - speed * 0.08);
    ballMesh.children.forEach(child => {
      if ((child as Mesh).material && (child as Mesh).material instanceof MeshStandardMaterial) {
        ((child as Mesh).material as MeshStandardMaterial).opacity = ghostBallOpacity;
        ((child as Mesh).material as MeshStandardMaterial).transparent = true;
      }
    });
  }

  // Daily paddle scale
  const pScale = getDailyPaddleScale();
  if (pScale !== 1.0) {
    playerPaddle.scale.set(pScale, pScale, pScale);
  }

  // Daily ball scale
  const bScale = getDailyBallScale();
  if (bScale !== 1.0) {
    ballMesh.scale.set(bScale, bScale, bScale);
  }

  // Wind particles visual
  if (gsm.windForce > 0 && ball.active) {
    spawnWindParticle();
  }
  updateWindParticles(dt);
}

function spawnWindParticle() {
  if (windParticles.length >= 15 || Math.random() > 0.1) return;
  const theme = gsm.getTheme();
  const geo = new SphereGeometry(0.005, 3, 3);
  const mat = new MeshBasicMaterial({ color: 0xaaddff, transparent: true, opacity: 0.3 });
  const mesh = new Mesh(geo, mat);
  mesh.position.set(
    ball.position.x + (Math.random() - 0.5) * 0.5,
    ball.position.y + (Math.random() - 0.5) * 0.3,
    ball.position.z + (Math.random() - 0.5) * 0.5
  );
  world.scene.add(mesh);
  const vel = new Vector3(
    Math.cos(gsm.windDirection) * gsm.windForce * 0.5,
    (Math.random() - 0.5) * 0.2,
    Math.sin(gsm.windDirection) * gsm.windForce * 0.3
  );
  windParticles.push({ mesh, vel, life: 1.0 });
}

function updateWindParticles(dt: number) {
  for (let i = windParticles.length - 1; i >= 0; i--) {
    const p = windParticles[i];
    p.mesh.position.addScaledVector(p.vel, dt);
    p.life -= dt * 2;
    (p.mesh.material as MeshBasicMaterial).opacity = p.life * 0.3;
    if (p.life <= 0) {
      world.scene.remove(p.mesh);
      windParticles.splice(i, 1);
    }
  }
}

// === HUD ===
function updateHUD() {
  const doc = getDoc('hud');
  if (!doc) return;

  if (gsm.mode === 'match' || gsm.mode === 'tournament') {
    setText(doc, 'hud-score', `${gsm.playerScore} - ${gsm.aiScore}`);
    const setsLabel = gsm.mode === 'tournament' ? 'Tournament' : `Sets: ${gsm.playerSets} - ${gsm.aiSets}`;
    setText(doc, 'hud-sets', setsLabel);
  } else if (gsm.mode === 'speed') {
    setText(doc, 'hud-score', `Hits: ${gsm.speedHits}`);
    setText(doc, 'hud-sets', `Time: ${Math.max(0, 60 - Math.floor(gsm.speedTimer))}s`);
  } else if (gsm.mode === 'rally') {
    setText(doc, 'hud-score', `Rally: ${gsm.rallyCount}`);
    setText(doc, 'hud-sets', `Best: ${gsm.bestRally}`);
  } else {
    setText(doc, 'hud-score', `${gsm.playerScore} - ${gsm.aiScore}`);
    setText(doc, 'hud-sets', gsm.mode.toUpperCase());
  }

  setText(doc, 'hud-serve', gsm.serving === 'player' ? 'YOUR SERVE' : 'AI SERVE');

  // Show combo/streak, deuce status, and camera mode
  let comboText = '';
  if (gsm.isDeuce) comboText = '⚡ DEUCE';
  else if (gsm.currentStreak > 1) comboText = `Streak: ${gsm.currentStreak}`;
  setText(doc, 'hud-combo', comboText);
}

main();

